import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        LinkedHashSet<String> dilihat = new LinkedHashSet<>();
        while (in.hasNextLine()) {
            dilihat.add(in.nextLine().trim());
        }
        List<String> semua = new ArrayList<>(dilihat);
        Collections.reverse(semua);
        System.out.println(semua.subList(0, Math.min(n, semua.size())));
    }
}

cards.solution:
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        LinkedHashSet<String> dilihat = new LinkedHashSet<>();
        while (in.hasNextLine()) {
            dilihat.addLast(in.nextLine().trim());
        }
        List<String> hasil = dilihat.reversed().stream().limit(n).toList();
        System.out.println(hasil);
    }
}
